(()=>{'use strict';
 const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>Array.from(r.querySelectorAll(s));
 const contents=$('.mag-contents details');if(contents&&matchMedia('(max-width:800px)').matches)contents.open=false;
 const progress=$('.mag-reading-progress>span');const story=$('.mag-story');
 if(progress&&story){let scheduled=false;const draw=()=>{const total=story.offsetHeight-innerHeight;progress.style.width=Math.min(100,Math.max(0,(scrollY-story.offsetTop)/Math.max(1,total)*100))+'%';scheduled=false;};addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(draw);}},{passive:true});draw();}
 if('IntersectionObserver'in window){const watch=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){$$('.mag-contents a[aria-current]').forEach(x=>x.removeAttribute('aria-current'));const a=$$('.mag-contents a').find(x=>x.hash==='#'+entry.target.id);if(a)a.setAttribute('aria-current','location');}},{rootMargin:'-15% 0px -65% 0px'});$$('.mag-prose h2[id]').forEach(x=>watch.observe(x));}
 $$('[data-copy-link]').forEach(b=>b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.origin+location.pathname);b.textContent='Link copied ✓';}catch{b.textContent='Copy the address above';}}));
 const layer=$('#overshirt-layer'),fit=$('#overshirt-fit-result');if(layer&&fit)layer.addEventListener('change',()=>{fit.textContent={tee:'Button it over your tee, cross your arms and reach forward. Look for smooth movement through the back without pulling at the buttons.',knit:'Try the actual knit underneath. Bend both elbows and sit down: the upper sleeves and back should move freely without the front ballooning.',hoodie:'Check the sleeve and armhole room over your hoodie before sizing up. If the shoulders become too wide, choose a roomier cut rather than a larger size.'}[layer.value];});
 const search=$('[data-story-search]'),filters=$$('[data-story-topic]');let topic='all';function filter(){let n=0;const q=(search?.value||'').trim().toLowerCase();$$('[data-story-grid]>.mag-story-card').forEach(x=>{const show=(!q||x.dataset.search.includes(q))&&(topic==='all'||x.dataset.topic===topic);x.hidden=!show;if(show)n++;});const count=$('[data-story-count]');if(count)count.textContent=n+' '+(n===1?'story':'stories');const empty=$('.mag-empty');if(empty)empty.hidden=n>0;}if(search)search.addEventListener('input',filter);filters.forEach(b=>b.addEventListener('click',()=>{topic=b.dataset.storyTopic;filters.forEach(x=>x.setAttribute('aria-pressed',String(x===b)));filter();}));
 let lightbox;function showImage(a,event){if(!window.HTMLDialogElement)return;const im=$('img',a);if(!im)return;event.preventDefault();if(!lightbox){lightbox=document.createElement('dialog');lightbox.className='mag-lightbox';const close=document.createElement('button');close.type='button';close.textContent='×';close.setAttribute('aria-label','Close larger image');const img=document.createElement('img');const caption=document.createElement('p');lightbox.append(close,img,caption);document.body.append(lightbox);close.addEventListener('click',()=>lightbox.close());lightbox.addEventListener('click',e=>{if(e.target===lightbox)lightbox.close();});} $('img',lightbox).src=a.href;$('img',lightbox).alt=im.alt;$('p',lightbox).textContent=im.alt;lightbox.showModal();}
 $$('[data-lightbox]').forEach(a=>a.addEventListener('click',e=>showImage(a,e)));
 // Add an accessible zoom action only to images that already link to a full-size asset.
 $$('.mag-prose a:has(img)').filter(a=>!a.hasAttribute('data-dg-zoom')&&/\.(webp|jpe?g|png)(\?|$)/i.test(a.href)).forEach(a=>a.addEventListener('click',e=>showImage(a,e)));
})();
